SELECT HEX(r.hash) hash,r.page_id,t.title,r.first_at,r.born_rev,r.current,e.user editor,e.comment,CONCAT('https://fi.wikipedia.org/?oldid=',CAST(r.born_rev AS UNSIGNED)) link FROM ranked r JOIN titles t USING(page_id) LEFT JOIN wtt.edit e ON e.rev_id=r.born_rev WHERE r.hash IN (UNHEX('DC4E2656304FF854'),UNHEX('173B3C202DBA03B4'),UNHEX('C794BF272254E50C'),UNHEX('DC700E10130C116E'),UNHEX('4318E57D7B6F25BF'),UNHEX('86B3D75756CD1381'),UNHEX('F9520AFAAAEA6E60'),UNHEX('37F201A358090759'),UNHEX('39D59C200556B9C7'),UNHEX('5B7B3BF97C327681'),UNHEX('FDA4AE5F4E1514FA'),UNHEX('EFE87464A796E9E1'),UNHEX('B422501F92C80E2B'),UNHEX('E5604A609D32B713'),UNHEX('E838FDD06BDE2C18'),UNHEX('45B2AD1C470A4B2D'),UNHEX('00B71683D18C27FC'),UNHEX('05EEB3B62E887B4D'),UNHEX('CB96494B14AB4A6C'),UNHEX('112DE68249D63609'),UNHEX('EED532A656816842'),UNHEX('355F57AA05A8A845'),UNHEX('4B98ED9BCBC19C5C'),UNHEX('3BB8B6A539444B84'),UNHEX('D75FA1BE85F1AC08'),UNHEX('CAB0430E5040DA55'),UNHEX('207D5E795A918F62'),UNHEX('0750FD5747D9421E'),UNHEX('F2DC727B22346779'),UNHEX('9FD4923B72E8E4E3')) ORDER BY r.hash,r.first_at,r.page_id;
